pub(super) fn read_packet(r: &mut Reader<'_>, format: u16, id: u8) -> Result<Packet, ParseError> {
    Ok(match id {
        0 => Packet::Motion(Box::new(PacketMotionData::read(r, format)?)),
        1 => Packet::Session(Box::new(PacketSessionData::read(r, format)?)),
        2 => Packet::Lap(Box::new(PacketLapData::read(r, format)?)),
        3 => Packet::Event(Box::new(super::Event::read(r, format)?)),
        4 => Packet::Participants(Box::new(PacketParticipantsData::read(r, format)?)),
        5 => Packet::CarSetup(Box::new(PacketCarSetupData::read(r, format)?)),
        6 => Packet::CarTelemetry(Box::new(PacketCarTelemetryData::read(r, format)?)),
        7 => Packet::CarStatus(Box::new(PacketCarStatusData::read(r, format)?)),
        8 => Packet::FinalClassification(Box::new(PacketFinalClassificationData::read(r, format)?)),
        9 => Packet::LobbyInfo(Box::new(PacketLobbyInfoData::read(r, format)?)),
        10 => Packet::CarDamage(Box::new(PacketCarDamageData::read(r, format)?)),
        11 => Packet::SessionHistory(Box::new(PacketSessionHistoryData::read(r, format)?)),
        12 => Packet::TyreSets(Box::new(PacketTyreSetsData::read(r, format)?)),
        13 => Packet::MotionEx(Box::new(PacketMotionExData::read(r, format)?)),
        14 => Packet::TimeTrial(Box::new(PacketTimeTrialData::read(r, format)?)),
        15 => Packet::LapPositions(Box::new(PacketLapPositionsData::read(r, format)?)),
        16 => Packet::CarTelemetry2(Box::new(PacketCarTelemetry2Data::read(r, format)?)),
        _ => return Err(ParseError::UnsupportedPacketId { format, id }),
    })
}
